/**
 * Charset tables (SPEC-v3 §11.1): exhaustive parity with the Python
 * bdfparser. `test/fixtures/charsets.json` is generated by
 * `tools/gen_charsets.py` from the Python library (the reference): SHA-256 of
 * `cp2char` over the whole code space (0x0000–0xFFFF, a few larger codes and
 * every 4-byte GB18030 code) and of `char2cp` over the BMP plus astral
 * characters, for every key of the canonical charset table (and the GL form
 * of the GL-capable sets), and canonicalisation vectors.
 */
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import '../src/cjk'
import {
  canonicalCharset,
  char2cp,
  charsetKeys,
  charsetProps,
  cp2char,
  getCodec,
  registerCharsetTables,
  sanitizeCharset,
} from '../src/encoding'
import { Font } from '../src/Font'
import { setWarningHandler } from '../src/warn'

type Fixture = {
  extra_codes: number[]
  astral_stride: number
  astral_tables: [number, number][]
  table: Record<
    string,
    {
      codec: string | null
      kind: string
      gl: boolean
      forcegl: boolean
      props: [string, string]
      aliases: string[]
    }
  >
  hashes: Record<
    string,
    { cp2char: string; char2cp: string; mapped: number; cp2char4?: string }
  >
  canonical: {
    names: [string, string, string][]
    pairs: [string | null, string | number | null, string][]
    props: [string, [string, string]][]
  }
}

const fixture = JSON.parse(
  readFileSync('./test/fixtures/charsets.json', 'utf8')
) as Fixture

const astral = (() => {
  const s = new Set<number>([0x10000, 0x10ffff])
  for (let u = 0x10000; u < 0x110000; u += fixture.astral_stride) {
    s.add(u)
  }
  for (const [a, b] of fixture.astral_tables) {
    for (let u = a; u <= b; u++) {
      s.add(u)
    }
  }
  return [...s].sort((a, b) => a - b)
})()

const sha = (lines: string[]): string => {
  const h = createHash('sha256')
  // in chunks: one string per dump would be several MB
  for (let i = 0; i < lines.length; i += 4096) {
    h.update(lines.slice(i, i + 4096).join(''))
  }
  return h.digest('hex')
}

type Codec = ReturnType<typeof getCodec>

const cp2charDump = (c: Codec, codes: Iterable<number>): string => {
  const out: string[] = []
  for (const code of codes) {
    const ch = c.cp2char(code)
    if (ch !== null) {
      out.push(
        `${code.toString(16)}:${(ch.codePointAt(0) as number).toString(16)}\n`
      )
    }
  }
  return sha(out)
}

const char2cpDump = (c: Codec, cps: Iterable<number>): string => {
  const out: string[] = []
  for (const u of cps) {
    const code = c.char2cp(String.fromCodePoint(u))
    if (code !== null) {
      out.push(`${u.toString(16)}:${code.toString(16)}\n`)
    }
  }
  return sha(out)
}

function* range(a: number, b: number): Generator<number> {
  for (let i = a; i < b; i++) {
    yield i
  }
}

function* gb4Codes(): Generator<number> {
  for (let b0 = 0x81; b0 <= 0xfe; b0++) {
    for (let b1 = 0x30; b1 <= 0x39; b1++) {
      for (let b2 = 0x81; b2 <= 0xfe; b2++) {
        for (let b3 = 0x30; b3 <= 0x39; b3++) {
          yield b0 * 0x1000000 + (b1 << 16) + (b2 << 8) + b3
        }
      }
    }
  }
}

const codecFor = (name: string): Codec => {
  const [key, gl] = name.split('/')
  return getCodec(key, gl === 'gl' ? { gl: true } : {})
}

describe('charset tables: exact parity with Python (generated fixture)', () => {
  test('the fixture covers every key of the JS table, and only those', () => {
    expect(charsetKeys().sort()).toEqual(Object.keys(fixture.table).sort())
    for (const [key, info] of Object.entries(fixture.table)) {
      const c = getCodec(key)
      expect(c.charset).toBe(key)
      expect(c.known).toBe(true)
      expect(c.kind).toBe(info.kind)
      expect(c.gl94).toBe(info.gl || info.forcegl)
      expect(c.gl).toBe(info.forcegl)
      expect(c.exact).toBe(true)
      expect(charsetProps(key)).toEqual(info.props)
      for (const a of info.aliases) {
        expect(canonicalCharset(a)).toBe(key)
      }
    }
  })

  for (const [name, h] of Object.entries(fixture.hashes)) {
    test(`${name}: cp2char over the code space, char2cp over the characters`, () => {
      const c = codecFor(name)
      expect(
        cp2charDump(c, [...range(0, 0x10000), ...fixture.extra_codes])
      ).toBe(h.cp2char)
      expect(char2cpDump(c, [...range(0, 0x10000), ...astral])).toBe(h.char2cp)
      let mapped = 0
      for (let code = 0; code < 0x10000; code++) {
        if (c.cp2char(code) !== null) {
          mapped++
        }
      }
      expect(mapped).toBe(h.mapped)
      if (h.cp2char4 !== undefined) {
        expect(cp2charDump(c, gb4Codes())).toBe(h.cp2char4)
      }
    })
  }

  test('canonicalisation vectors', () => {
    for (const [name, sanitized, canonical] of fixture.canonical.names) {
      expect(sanitizeCharset(name), name).toBe(sanitized)
      expect(canonicalCharset(name), name).toBe(canonical)
    }
    for (const [reg, enc, key] of fixture.canonical.pairs) {
      expect(sanitizeCharset(reg, enc), `${reg} ${enc}`).toBe(key)
    }
    for (const [key, props] of fixture.canonical.props) {
      expect(charsetProps(key), key).toEqual(props)
    }
  })
})

describe('charset tables: spot checks', () => {
  test('strict round trip and byte-length rule (SPEC-v3 §11.1)', () => {
    // Shift_JIS encodes '¥' as 0x5C, which decodes to '\'
    expect(char2cp('¥', 'shiftjis')).toBeNull()
    expect(cp2char(0x5c, 'shiftjis')).toBe('\\')
    // JIS X 0212 (3 bytes) is not a valid EUC-JP / JIS X 0208 font code
    expect(char2cp('ß', 'eucjp')).toBeNull()
    expect(cp2char(0x8fa9ce, 'eucjp')).toBeNull()
    // Hangul outside KS X 1001: no 8-byte composition sequences
    expect(char2cp('갂', 'euckr')).toBeNull()
    expect(char2cp('갂', 'cp949')).toBe(0x8141)
    // GB18030 4-byte codes (algorithmic ranges)
    expect(char2cp('😀', 'gb18030')).toBe(0x9439fc36)
    expect(cp2char(0x9439fc36, 'gb18030')).toBe('😀')
    expect(char2cp('\u0080', 'gb18030')).toBe(0x81308130)
    expect(cp2char(0x81308130, 'gb18030')).toBe('\u0080')
    expect(cp2char(0xe3329a35, 'gb18030')).toBe('\u{10ffff}')
    expect(cp2char(0xe3329a36, 'gb18030')).toBeNull()
    expect(cp2char(0x8130a1a1, 'gb18030')).toBeNull()
    expect(cp2char(0x100000000, 'gb18030')).toBeNull()
    expect(cp2char(0x81308130, 'gbk')).toBeNull()
    // two characters are not one code
    expect(cp2char(0x4142, 'gbk')).toBeNull()
    // Big5-HKSCS 0x8862 decodes to two code points (Ê + U+0304): not a code
    expect(cp2char(0x8862, 'big5hkscs')).toBeNull()
    // the code space of single-byte charsets is 0x00-0xFF
    expect(cp2char(0x41, 'cp1252')).toBe('A')
    expect(cp2char(0x0141, 'cp1252')).toBeNull()
    expect(cp2char(0x81, 'cp1252')).toBeNull() // undefined in Python's cp1252
    expect(cp2char(0x80, 'iso88591')).toBe('\x80')
    expect(cp2char(0x80, 'iso88599')).toBe('\x80') // not windows-1254
    expect(cp2char(0xae, 'koi8u')).toBe('╝') // not KOI8-RU
    // the new code pages
    expect(cp2char(0xb0, 'cp437')).toBe('░')
    expect(cp2char(0x8740, 'cp932')).toBe('①')
    // Python's cp936 is its gbk codec (no 0x80 euro sign)
    expect(cp2char(0x80, 'cp936')).toBeNull()
    expect(cp2char(0x8140, 'cp936')).toBe('丂')
    expect(cp2char(0xa140, 'cp950')).toBe('　')
    expect(cp2char(0x8861, 'johab')).toBe('가')
    // GL form
    expect(getCodec('gb2312', { gl: true }).cp2char(0x3021)).toBe('啊')
    expect(getCodec('gb2312', { gl: true }).char2cp('啊')).toBe(0x3021)
    expect(getCodec('gb2312', { gl: true }).cp2char(0x0e21)).toBeNull()
    expect(getCodec('iso2022cn').cp2char(0x3021)).toBe('啊')
    expect(getCodec('jisx0208', { gl: true }).char2cp('｡')).toBeNull()
    expect(getCodec('big5', { gl: true }).gl).toBe(false)
    // invalid input
    expect(() => char2cp('ab', 'gbk')).toThrow(TypeError)
    expect(cp2char(-1, 'gbk')).toBeNull()
    expect(cp2char(1.5, 'gbk')).toBeNull()
  })

  test('charsets no longer known: hz, WHATWG-only labels (Unicode + one warning)', () => {
    const warnings: string[] = []
    const prev = setWarningHandler((m) => warnings.push(m))
    try {
      for (const name of ['hz', 'hz-gb-2312', 'koi8-ru', 'x-mac-cyrillic']) {
        expect(getCodec(name).known, name).toBe(false)
        expect(cp2char(0x4e2d, name)).toBe('中')
        expect(char2cp('中', name)).toBe(0x4e2d)
      }
      expect(warnings).toEqual([
        "Unknown charset 'hz', characters are mapped to codepoints as Unicode",
        "Unknown charset 'hzgb2312', characters are mapped to codepoints as Unicode",
        "Unknown charset 'koi8ru', characters are mapped to codepoints as Unicode",
        "Unknown charset 'xmaccyrillic', characters are mapped to codepoints as Unicode",
      ])
    } finally {
      setWarningHandler(prev)
    }
  })

  test('registerCharsetTables: validation, re-registration', () => {
    expect(() =>
      registerCharsetTables(
        null as unknown as Parameters<typeof registerCharsetTables>[0]
      )
    ).toThrow(TypeError)
    // re-registering the same tables is harmless
    registerCharsetTables({ tables: {} })
    expect(cp2char(0xb0a1, 'gb2312')).toBe('啊')
  })

  test('a GB 2312 font: charset, GL detection, conversion, charsetconvert', () => {
    const font = Font.create({ pixelsize: 2 })
    font.newglyph(0x554a) // 啊
    font.newglyph(0x1f600) // 😀
    font.charsetconvert('gb2312')
    expect(font.charset).toBe('gb2312')
    expect([...font.glyphs.keys()]).toEqual([0x3021])
    expect(font.props.charset_registry).toBe('GB2312.1980')
    font.charsetconvert('gb18030')
    expect([...font.glyphs.keys()]).toEqual([0xb0a1])
    expect(font.glyph('啊')?.cp()).toBe(0xb0a1)
  })
})
